import { chromium } from '@playwright/test'

const base = process.argv[2]
if (!base) throw new Error('usage: ui-check.ts <baseUrl>')

const browser = await chromium.launch()
const failures: string[] = []
function check(name: string, ok: boolean, detail = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`)
  if (!ok) failures.push(name)
}

// 1. Loading state: hold the API response so the loading text is observable.
{
  const page = await browser.newPage()
  let release!: () => void
  const gate = new Promise<void>((r) => (release = r))
  await page.route('**/api/files', async (route) => {
    await gate
    await route.continue()
  })
  await page.goto(base)
  const loading = await page.getByRole('status').textContent()
  check('loading state shown while request pending', loading?.includes('Loading files') ?? false, loading ?? '')
  release()
  await page.waitForSelector('table')
  await page.close()
}

// 2. Ready state against the real API.
{
  const page = await browser.newPage()
  await page.goto(base)
  await page.waitForSelector('table')
  const rows = await page.$$eval('tbody tr', (trs) =>
    trs.map((tr) => Array.from(tr.querySelectorAll('td')).map((td) => td.textContent?.trim() ?? '')),
  )
  console.log('rows:', JSON.stringify(rows))
  const expected = [
    ['Claude', 'empty.md'],
    ['Claude', 'subagents/implementer.md'],
    ['Claude', 'workflow.md'],
    ['Pi', 'skills/review.md'],
    ['Pi', 'workflow.md'],
  ]
  check('all five Markdown fixtures listed (nested + empty)', JSON.stringify(rows) === JSON.stringify(expected))
  check('notes.txt excluded', !rows.some((r) => r[1].includes('notes.txt')))
  const workflows = rows.filter((r) => r[1] === 'workflow.md')
  check('two workflow.md rows distinguishable by source', workflows.length === 2 && new Set(workflows.map((r) => r[0])).size === 2)
  check('no loading/error text in ready state', (await page.locator('.status').count()) === 0)
  await page.close()
}

// 3. Empty state.
{
  const page = await browser.newPage()
  await page.route('**/api/files', (route) => route.fulfill({ json: { files: [] } }))
  await page.goto(base)
  await page.waitForSelector('.status')
  const text = await page.locator('.status').textContent()
  check('empty state message', text?.includes('No Markdown files found') ?? false, text ?? '')
  check('no table in empty state', (await page.locator('table').count()) === 0)
  await page.close()
}

// 4. Error state (server error).
{
  const page = await browser.newPage()
  await page.route('**/api/files', (route) => route.fulfill({ status: 500, body: 'boom' }))
  await page.goto(base)
  await page.waitForSelector('[role=alert]')
  const text = await page.getByRole('alert').textContent()
  check('error state on HTTP 500', (text?.includes('Could not load files') && text.includes('500')) ?? false, text ?? '')
  await page.close()
}

// 5. Error state (network failure).
{
  const page = await browser.newPage()
  await page.route('**/api/files', (route) => route.abort('connectionrefused'))
  await page.goto(base)
  await page.waitForSelector('[role=alert]')
  const text = await page.getByRole('alert').textContent()
  check('error state on network failure', text?.includes('Could not load files') ?? false, text ?? '')
  await page.close()
}

await browser.close()
if (failures.length) {
  console.log(`\n${failures.length} check(s) failed`)
  process.exit(1)
}
console.log('\nall UI checks passed')

