node -e '
const fs=require("fs");
const lines=fs.readFileSync(process.env.HOME+"/.claude/projects/-home-agentops-dev-md-manager-c/06d06f6c-9acf-405f-a86a-2c47a857c2c1.jsonl","utf8").trim().split("\n").map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean);
let turn=0, turns=[], seen=new Set();
for(const m of lines){
  if(m.type==="user" && m.message && typeof m.message.content==="string"){ turn++; turns[turn]={label:m.message.content.slice(0,60).replace(/\s+/g," "),ts:m.timestamp,calls:0,in:0,cr:0,cc:0,out:0,last:m.timestamp}; }
  if(m.type==="user" && m.message && Array.isArray(m.message.content) && m.message.content.some(c=>c.type==="text") && !m.message.content.some(c=>c.type==="tool_result")){ turn++; turns[turn]={label:m.message.content.find(c=>c.type==="text").text.slice(0,60).replace(/\s+/g," "),ts:m.timestamp,calls:0,in:0,cr:0,cc:0,out:0,last:m.timestamp}; }
  if(m.type==="assistant" && m.message && m.message.usage && turns[turn]){
    const id=m.message.id; if(seen.has(id)) continue; seen.add(id);
    const u=m.message.usage, t=turns[turn];
    t.calls++; t.in+=u.input_tokens||0; t.cr+=u.cache_read_input_tokens||0; t.cc+=u.cache_creation_input_tokens||0; t.out+=u.output_tokens||0; t.last=m.timestamp;
  }
}
const tot={calls:0,in:0,cr:0,cc:0,out:0};
for(const t of turns.filter(Boolean)){
  const mins=((new Date(t.last)-new Date(t.ts))/60000).toFixed(1);
  console.log(`[${t.ts.slice(11,19)} +${mins}m] calls=${t.calls} input=${t.in} cache_read=${t.cr} cache_create=${t.cc} output=${t.out} :: ${t.label}`);
  for(const k in tot) tot[k]+=t[k];
}
console.log("TOTAL", JSON.stringify(tot));
'

